// Screenshots de showcase embutidos como base64 — Hostinger não serve public/.
const SHOWCASE: Record<string, { mime: string; data: string }> = {
  'alertas.jpg': { mime: 'image/jpeg', data: '' },
  'dashboard.jpg': { mime: 'image/jpeg', data: '' },
  'funil.jpg': { mime: 'image/jpeg', data: '' },
  'ia-gargalos.jpg': { mime: 'image/jpeg', data: '' },
  'metas.jpg': { mime: 'image/jpeg', data: '' },
  'origem.jpg': { mime: 'image/jpeg', data: '' },
}

export const dynamic = 'force-dynamic'

export async function GET(
  _req: Request,
  { params }: { params: Promise<{ name: string }> }
) {
  const { name } = await params
  const entry = SHOWCASE[name]
  if (!entry) return new Response(null, { status: 404 })
  const buf = Buffer.from(entry.data, 'base64')
  return new Response(buf, {
    headers: {
      'Content-Type': entry.mime,
      'Cache-Control': 'public, max-age=31536000, immutable',
      'Content-Length': String(buf.length),
    },
  })
}
